Trigger.TriggerText:
begin
  select nome into :prd.desc_categoria from categorias where id = :prd.categoria_id;
exception
  when no_data_found then :prd.desc_categoria := null;
end;
begin
  select razao_social into :prd.desc_fornecedor from fornecedores f where f.id = :prd.fornecedor_id;
exception when others then null;
end;

select produtos_seq.nextval into :prd.id from dual;
:prd.usuario_alt := user;
:prd.dt_alt := sysdate;

if :prd.preco_venda < :prd.preco_custo then
  message('Preço de venda abaixo do custo');
  raise form_trigger_failure;
end if;

if :prd.codigo is null then
  message('Informe o código');
  raise form_trigger_failure;
end if;

if :prd.preco_venda < 0 then
  message('Preço não pode ser negativo');
  raise form_trigger_failure;
end if;

declare
  cursor c is select custo from compras where produto_id = :prd.id order by data desc;
  v number;
begin
  open c; fetch c into v; close c;
  if v is not null then
    :prd.preco_custo := v;
    :prd.preco_venda := round(v * 1.3, 2);
  end if;
end;

if :estoque.quantidade <= 0 then
  message('Quantidade inválida');
  raise form_trigger_failure;
end if;

ProgramUnit.ProgramUnitText:
procedure exporta_csv is
  f text_io.file_type;
begin
  f := text_io.fopen('c:\temp\produtos.csv', 'w');
  text_io.put_line(f, :prd.codigo);
  text_io.fclose(f);
end;

function margem(p_custo number, p_venda number) return number is
begin
  if nvl(p_custo,0) = 0 then return null; end if;
  return round((p_venda - p_custo) / p_custo * 100, 2);
end;
